const rows = $('Read Sales').all().map(i => i.json).filter(r => r['Order ID']);
function toIso(v) {
  if (v === undefined || v === null || v === '') return '';
  if (typeof v === 'number') { return new Date(Date.UTC(1899, 11, 30) + v * 86400000).toISOString().slice(0, 10); }
  return String(v).slice(0, 10);
}
const dates = rows.map(r => toIso(r['Date'])).filter(Boolean).sort();
const distinct = (col) => Array.from(new Set(rows.map(r => String(r[col]).trim()))).sort();
const schema = [
  'Table: Sales (one row per order, ' + rows.length + ' rows)',
  'Columns:',
  '- Order ID (text)',
  '- Date (YYYY-MM-DD, from ' + dates[0] + ' to ' + dates[dates.length - 1] + ')',
  '- Region (text): ' + distinct('Region').join(', '),
  '- Product (text): ' + distinct('Product').join(', '),
  '- Channel (text): ' + distinct('Channel').join(', '),
  '- Units (number)',
  '- Revenue (number, USD)',
  '- Cost (number, USD)',
  'Derived metrics available: revenue, cost, profit (revenue - cost), margin_pct (profit / revenue * 100), units, orders (row count), avg_order_value (revenue / orders).'
].join('\n');
return [{ json: { schema, rowCount: rows.length } }];

const plan = $input.first().json.output || {};
const rows = $('Read Sales').all().map(i => i.json).filter(r => r['Order ID']);
function toIso(v) {
  if (typeof v === 'number') { return new Date(Date.UTC(1899, 11, 30) + v * 86400000).toISOString().slice(0, 10); }
  return String(v).slice(0, 10);
}
const num = (v) => { const n = Number(String(v).replace(/[^0-9.\-]/g, '')); return isNaN(n) ? 0 : n; };
const fail = (reason) => [{ json: { ok: false, reason, plan } }];

if (!plan.answerable) return fail(plan.reason || 'The question needs data that is not in the Sales table.');

const METRICS = ['revenue', 'cost', 'profit', 'margin_pct', 'units', 'orders', 'avg_order_value'];
const GROUPS = ['none', 'Region', 'Product', 'Channel', 'month'];
const metric = String(plan.metric || '').toLowerCase();
if (METRICS.indexOf(metric) < 0) return fail('Unsupported metric: ' + plan.metric);
const groupBy = GROUPS.indexOf(plan.group_by) >= 0 ? plan.group_by : 'none';

const distinct = (col) => Array.from(new Set(rows.map(r => String(r[col]).trim())));
const filters = [];
const fcols = [['Region', plan.filter_region], ['Product', plan.filter_product], ['Channel', plan.filter_channel]];
const active = {};
for (const pair of fcols) {
  const col = pair[0];
  const wanted = Array.isArray(pair[1]) ? pair[1].filter(x => String(x).trim()) : [];
  if (!wanted.length) continue;
  const known = distinct(col);
  const matched = [];
  for (const w of wanted) {
    const hit = known.find(k => k.toLowerCase() === String(w).trim().toLowerCase());
    if (!hit) return fail('There is no ' + col + ' called "' + w + '" in the data. Available: ' + known.join(', ') + '.');
    matched.push(hit);
  }
  active[col] = matched;
  filters.push(col + ' = ' + matched.join(' / '));
}
const from = /^\d{4}-\d{2}-\d{2}$/.test(plan.date_from || '') ? plan.date_from : '';
const to = /^\d{4}-\d{2}-\d{2}$/.test(plan.date_to || '') ? plan.date_to : '';
if (from) filters.push('from ' + from);
if (to) filters.push('to ' + to);

const sel = rows.filter(r => {
  const d = toIso(r['Date']);
  if (from && d < from) return false;
  if (to && d > to) return false;
  for (const col of Object.keys(active)) { if (active[col].indexOf(String(r[col]).trim()) < 0) return false; }
  return true;
});
if (!sel.length) return fail('No orders match those filters (' + (filters.join(', ') || 'none') + ').');

const groups = {};
for (const r of sel) {
  const key = groupBy === 'none' ? 'Total' : groupBy === 'month' ? toIso(r['Date']).slice(0, 7) : String(r[groupBy]).trim();
  if (!groups[key]) groups[key] = { revenue: 0, cost: 0, units: 0, orders: 0 };
  groups[key].revenue += num(r['Revenue']);
  groups[key].cost += num(r['Cost']);
  groups[key].units += num(r['Units']);
  groups[key].orders += 1;
}
const val = (g) => {
  const profit = g.revenue - g.cost;
  switch (metric) {
    case 'revenue': return g.revenue;
    case 'cost': return g.cost;
    case 'profit': return profit;
    case 'margin_pct': return g.revenue ? (profit / g.revenue) * 100 : 0;
    case 'units': return g.units;
    case 'orders': return g.orders;
    default: return g.orders ? g.revenue / g.orders : 0;
  }
};
let table = Object.keys(groups).map(k => ({ label: k, value: Math.round(val(groups[k]) * 100) / 100, orders: groups[k].orders }));
if (groupBy === 'month') {
  table.sort((a, b) => (a.label < b.label ? -1 : 1));
} else {
  table.sort((a, b) => (plan.sort === 'asc' ? a.value - b.value : b.value - a.value));
}
const topN = Math.max(0, Math.min(Number(plan.top_n) || 0, 50));
if (topN && groupBy !== 'none') table = table.slice(0, topN);

const isMoney = ['revenue', 'cost', 'profit', 'avg_order_value'].indexOf(metric) >= 0;
const unit = isMoney ? 'USD' : metric === 'margin_pct' ? '%' : metric;

let chartUrl = '';
const chartType = ['bar', 'line', 'pie'].indexOf(plan.chart) >= 0 ? plan.chart : 'none';
if (chartType !== 'none' && groupBy !== 'none' && table.length > 1) {
  const cfg = {
    type: chartType === 'bar' ? 'bar' : chartType,
    data: { labels: table.map(t => t.label), datasets: [{ label: metric + ' (' + unit + ')', data: table.map(t => t.value), backgroundColor: '#2563eb', borderColor: '#2563eb', fill: false }] },
    options: { plugins: { legend: { display: chartType === 'pie' } }, title: { display: true, text: metric + (groupBy === 'none' ? '' : ' by ' + groupBy) } }
  };
  chartUrl = 'https://quickchart.io/chart?w=700&h=380&bkg=white&c=' + encodeURIComponent(JSON.stringify(cfg));
}
return [{ json: {
  ok: true, metric, unit, groupBy, filters: filters.length ? filters.join(', ') : 'none',
  ordersMatched: sel.length, table, chartUrl,
  question: $('Called by Router (analytics)').first().json.text
} }];

