const r = $('Run analysis').first().json;
const raw = String($input.first().json.text || '');
const fmt = (v) => {
  if (r.unit === 'USD') return '$' + Number(v).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (r.unit === '%') return Number(v).toFixed(1) + '%';
  return Number(v).toLocaleString('en-US', { maximumFractionDigits: 0 });
};
const norm = (s) => String(s).replace(/,/g, '').replace(/\.0+$/, '');
const allowed = {};
const add = (v) => { const n = Number(v); if (!isNaN(n)) { allowed[norm(n)] = 1; allowed[norm(n.toFixed(2))] = 1; allowed[norm(n.toFixed(1))] = 1; allowed[norm(Math.round(n))] = 1; } };
r.table.forEach((t) => { add(t.value); add(t.orders); });
add(r.ordersMatched);
add(r.table.length);
String(r.filters || '').split(/[^0-9.]+/).forEach((x) => { if (x) allowed[norm(x)] = 1; });
String(r.question || '').split(/[^0-9.]+/).forEach((x) => { if (x) allowed[norm(x)] = 1; });
const found = raw.match(/\d[\d,]*\.?\d*/g) || [];
let bad = false;
for (const f of found) { const k = norm(f.replace(/\.$/, '')); const y = Number(k); if (allowed[k]) continue; if (y >= 2000 && y <= 2100) continue; bad = true; }
const fallback = '*' + r.metric + (r.groupBy !== 'none' ? ' by ' + r.groupBy : '') + '*: ' + r.table.slice(0, 5).map((t) => t.label + ' ' + fmt(t.value)).join(', ') + ' (' + r.ordersMatched + ' orders; filters: ' + r.filters + ').';
const answer = (bad || !raw.trim()) ? fallback : raw;
const blocks = [];
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: answer } });
if (r.groupBy !== 'none' && r.table.length > 1) {
  const w = Math.max.apply(null, r.table.map(t => t.label.length));
  const lines = r.table.slice(0, 12).map(t => t.label.padEnd(w) + '  ' + fmt(t.value));
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '```' + lines.join('\n') + '```' } });
}
if (r.chartUrl) blocks.push({ type: 'image', image_url: r.chartUrl, alt_text: 'Chart of ' + r.metric });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: ':bar_chart: Computed from the Sales sheet (' + r.ordersMatched + ' orders) | metric: ' + r.metric + ' | filters: ' + r.filters + ' | read-only' + (bad ? ' | summary generated from the table (AI wording had a number that did not match)' : '') }] });
return [{ json: { blocks: JSON.stringify({ blocks }), answer, used_fallback: bad } }];
